    // Precondition: confirm sign-in succeeded before asserting favourites behaviour
    await expect(page.getByText("My Account").first(), "Precondition: sign-in must succeed before testing favourites").toBeVisible();

    // Navigate to home and open first product
    await page.goto("/");
    await page.locator("[data-test='product-name']").first().click();

    // Add to favourites — action
    const favBtn = page.getByRole("button", { name: /favourites|favorite|wishlist/i }).first();
    await favBtn.click();

    // State after action: the favourite button shows the product was added
    await expect(favBtn, "Favourite button should indicate the product was added").toHaveClass(/active|selected|added|favourite/i);

    // Navigate to favourites list and confirm the product appears
    await page.goto("/account/favorites");
