    await page.goto("/account/favorites");

    // Precondition: there must be at least one item to remove
    await expect(page.locator("[data-test='product-name']").first(), "Precondition: favourites list must contain at least one product to test removal").toBeVisible();

    // Remove first item — action
    const removeBtn = page.getByRole("button", { name: /remove|delete/i }).first();
    await removeBtn.click();

    // State after action: removal is confirmed (button triggered, count changes)
    await expect(removeBtn, "Remove button should no longer be visible after removal").not.toBeVisible();

